/**
 * @file WebAssets.h
 * @brief Web panel files compiled into the firmware (generated by tools/web_embed.py).
 */
#pragma once

#include <cstddef>
#include <cstdint>

/// @brief One web panel file compiled into the firmware (gzip-compressed).
/// The table is generated by tools/web_embed.py from the web/ directory on every build.
struct WebAsset {
    const char* path;    ///< URL path, e.g. "/index.html".
    const char* mime;    ///< Content-Type.
    const uint8_t* data; ///< Gzip data.
    size_t size;         ///< Data size.
    const char* etag;    ///< Firmware version + content hash, in quotes.
};

extern const WebAsset WEB_ASSETS[];   ///< All panel files (src/generated/WebAssets.cpp).
extern const size_t WEB_ASSET_COUNT;  ///< Number of entries in WEB_ASSETS.
